BEGIN;
CREATE INDEX analytics_order_closed ON public.maintenance_orders(company_id,encerrada_em) WHERE status='encerrada';
CREATE INDEX analytics_order_opened ON public.maintenance_orders(company_id,data_abertura);
CREATE INDEX analytics_visit_dates ON public.workshop_visits(company_id,chegada_em,saida_em);
CREATE FUNCTION maintenance_private.analytics_command(c uuid,action text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid();date_start date:=coalesce(nullif(b->>'start','')::date,date_trunc('year',clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date);date_end date:=coalesce(nullif(b->>'end','')::date,(clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date);
 lo timestamptz;hi timestamptz;branch_filter text:=nullif(b->>'branch_id','');vehicle_filter uuid:=nullif(b->>'vehicle_id','')::uuid;partner_filter uuid:=nullif(b->>'partner_id','')::uuid;type_filter public.maintenance_type:=nullif(b->>'tipo','')::public.maintenance_type;
 page_number integer:=coalesce((b->>'page')::integer,1);page_size integer:=coalesce((b->>'size')::integer,20);report_name text:=coalesce(b->>'report','vehicles');result jsonb;BEGIN
 IF actor IS NULL OR NOT maintenance_private.partner_access(c) THEN RAISE EXCEPTION 'Sem acesso à empresa.' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.company_members WHERE company_id=c AND user_id=actor AND ativo FOR SHARE;
 PERFORM 1 FROM public.companies WHERE id=c AND ativo FOR SHARE;
 IF NOT FOUND OR NOT maintenance_private.partner_access(c) THEN RAISE EXCEPTION 'Acesso revogado.' USING ERRCODE='42501';END IF;
 IF action='context' THEN RETURN jsonb_build_object('branches',public.maintenance_branch_command(c,'list','{}')->'rows','vehicles',coalesce((SELECT jsonb_agg(jsonb_build_object('id',v.id,'placa',v.placa,'branch_id',v.branch_id) ORDER BY v.placa) FROM public.veiculos v WHERE v.company_id=c),'[]'::jsonb),'partners',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'nome',coalesce(p.nome_fantasia,p.razao_social)) ORDER BY p.razao_social) FROM public.maintenance_partners p WHERE p.company_id=c),'[]'::jsonb));END IF;
 IF action NOT IN ('dashboard','report') OR date_end<date_start OR date_end-date_start>3660 OR page_number NOT BETWEEN 1 AND 1000000 OR page_size NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Revise período, página e relatório (máximo 10 anos).';END IF;
 IF report_name NOT IN ('vehicles','partners','types','history','downtime') THEN RAISE EXCEPTION 'Relatório inválido.';END IF;
 IF branch_filter IS NOT NULL AND branch_filter<>'none' AND NOT EXISTS(SELECT 1 FROM public.maintenance_branches WHERE company_id=c AND id::text=branch_filter) THEN RAISE EXCEPTION 'Filial inválida nesta empresa.';END IF;
 IF vehicle_filter IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.veiculos WHERE id=vehicle_filter AND company_id=c) THEN RAISE EXCEPTION 'Veículo inválido nesta empresa.';END IF;
 IF partner_filter IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.maintenance_partners WHERE id=partner_filter AND company_id=c) THEN RAISE EXCEPTION 'Oficina inválida nesta empresa.';END IF;
 lo:=date_start::timestamp AT TIME ZONE 'America/Sao_Paulo';hi:=(date_end+1)::timestamp AT TIME ZONE 'America/Sao_Paulo';
 WITH all_orders AS MATERIALIZED (SELECT o.* FROM public.maintenance_orders o WHERE o.company_id=c AND (branch_filter IS NULL OR coalesce(o.branch_id::text,'none')=branch_filter) AND (vehicle_filter IS NULL OR o.vehicle_id=vehicle_filter) AND (partner_filter IS NULL OR o.partner_id=partner_filter) AND (type_filter IS NULL OR o.tipo=type_filter)),
 period_orders AS MATERIALIZED (SELECT * FROM all_orders WHERE data_abertura>=lo AND data_abertura<hi),
 costs AS MATERIALIZED (SELECT * FROM all_orders WHERE status='encerrada' AND encerrada_em>=lo AND encerrada_em<hi),
 active_orders AS (SELECT * FROM all_orders WHERE status NOT IN ('encerrada','cancelada')),
 fleet AS (SELECT v.* FROM public.veiculos v WHERE v.company_id=c AND (branch_filter IS NULL OR coalesce(v.branch_id::text,'none')=branch_filter) AND (vehicle_filter IS NULL OR v.id=vehicle_filter)),
 visit_ranges AS (SELECT w.vehicle_id,tstzrange(greatest(w.chegada_em,lo),least(coalesce(w.saida_em,clock_timestamp()),hi),'[)') span FROM public.workshop_visits w JOIN all_orders o ON o.id=w.order_id WHERE w.company_id=c AND w.chegada_em<hi AND coalesce(w.saida_em,clock_timestamp())>lo AND greatest(w.chegada_em,lo)<least(coalesce(w.saida_em,clock_timestamp()),hi)),
 merged AS (SELECT vehicle_id,range_agg(span) spans FROM visit_ranges GROUP BY vehicle_id),
 downtime AS (SELECT m.vehicle_id,sum(extract(epoch FROM upper(p.span)-lower(p.span))/3600) hours FROM merged m CROSS JOIN LATERAL unnest(m.spans) p(span) GROUP BY m.vehicle_id),
 finished_visits AS MATERIALIZED (SELECT w.*,o.previsao_entrega FROM public.workshop_visits w JOIN all_orders o ON o.id=w.order_id WHERE w.company_id=c AND w.saida_em>=lo AND w.saida_em<hi),
 repair_pairs AS (SELECT t.order_id,min(t.created_at) FILTER(WHERE t.dados->>'status_novo'='em_execucao') started,max(t.created_at) FILTER(WHERE t.dados->>'status_novo'='concluido') finished FROM public.maintenance_order_timeline t JOIN all_orders o ON o.id=t.order_id WHERE t.company_id=c GROUP BY t.order_id),
 readings AS (SELECT o.vehicle_id,o.km_abertura::numeric km,o.data_abertura recorded_at FROM public.maintenance_orders o WHERE o.company_id=c AND o.data_abertura>=lo AND o.data_abertura<hi
 UNION ALL SELECT w.vehicle_id,w.km_chegada,w.chegada_em FROM public.workshop_visits w WHERE w.company_id=c AND w.chegada_em>=lo AND w.chegada_em<hi
 UNION ALL SELECT w.vehicle_id,w.km_saida,w.saida_em FROM public.workshop_visits w WHERE w.company_id=c AND w.saida_em>=lo AND w.saida_em<hi),
 observed_km AS (SELECT vehicle_id,CASE WHEN count(DISTINCT recorded_at)>=2 AND max(km)>min(km) THEN max(km)-min(km) END km FROM readings WHERE km IS NOT NULL GROUP BY vehicle_id),
 vehicle_ids AS (SELECT vehicle_id FROM period_orders UNION SELECT vehicle_id FROM costs UNION SELECT vehicle_id FROM downtime),
 vehicle_metrics AS MATERIALIZED (SELECT v.id,v.placa,coalesce((SELECT sum(valor_total) FROM costs co WHERE co.vehicle_id=v.id),0) custo_total,(SELECT count(*) FROM costs co WHERE co.vehicle_id=v.id) total_os,(SELECT count(*) FROM period_orders po WHERE po.vehicle_id=v.id AND po.tipo='corretiva' AND po.status<>'cancelada') quebras,coalesce(d.hours,0) downtime_horas,k.km km_observado,(SELECT count(*) FROM public.workshop_visits w JOIN all_orders ao ON ao.id=w.order_id WHERE w.vehicle_id=v.id AND w.saida_em IS NULL) visitas_abertas FROM vehicle_ids ids JOIN public.veiculos v ON v.id=ids.vehicle_id AND v.company_id=c LEFT JOIN downtime d ON d.vehicle_id=v.id LEFT JOIN observed_km k ON k.vehicle_id=v.id),
 partner_ids AS (SELECT partner_id FROM period_orders UNION SELECT partner_id FROM costs UNION SELECT partner_id FROM finished_visits),
 partner_metrics AS MATERIALIZED (SELECT p.id,coalesce(p.nome_fantasia,p.razao_social) oficina,p.avaliacao_interna nota,(SELECT count(*) FROM costs co WHERE co.partner_id=p.id) total_os,coalesce((SELECT sum(valor_total) FROM costs co WHERE co.partner_id=p.id),0) custo_total,(SELECT avg(valor_total) FROM costs co WHERE co.partner_id=p.id) custo_medio,(SELECT avg(extract(epoch FROM fv.saida_em-fv.chegada_em)/3600) FROM finished_visits fv WHERE fv.partner_id=p.id) prazo_horas,(SELECT 100.0*count(*) FILTER(WHERE fv.saida_em<=fv.previsao_entrega)/nullif(count(*),0) FROM finished_visits fv WHERE fv.partner_id=p.id AND fv.previsao_entrega IS NOT NULL) sla_pct,(SELECT count(*) FROM finished_visits fv WHERE fv.partner_id=p.id AND fv.previsao_entrega IS NOT NULL) sla_amostras FROM partner_ids ids JOIN public.maintenance_partners p ON p.id=ids.partner_id AND p.company_id=c),
 type_metrics AS (SELECT tipo::text tipo,count(*) total_os,sum(valor_total) custo_total FROM costs GROUP BY tipo),
 monthly AS (SELECT to_char(month,'YYYY-MM') mes,coalesce((SELECT sum(co.valor_total) FROM costs co WHERE date_trunc('month',co.encerrada_em AT TIME ZONE 'America/Sao_Paulo')=month),0) custo FROM generate_series(date_trunc('month',date_start::timestamp),date_trunc('month',date_end::timestamp),'1 month') month),
 maintenance_now AS (SELECT count(*) n FROM fleet v WHERE CASE WHEN partner_filter IS NULL AND type_filter IS NULL THEN v.status='Manutenção' ELSE EXISTS(SELECT 1 FROM active_orders ao WHERE ao.vehicle_id=v.id) END),
 report_rows AS (
 SELECT vm.placa sort_key,jsonb_build_object('placa',vm.placa,'total_os',vm.total_os,'custo_total',vm.custo_total,'km_observado',vm.km_observado,'custo_km',vm.custo_total/nullif(vm.km_observado,0),'downtime_horas',vm.downtime_horas) row_data FROM vehicle_metrics vm WHERE report_name='vehicles'
 UNION ALL SELECT pm.oficina,jsonb_build_object('oficina',pm.oficina,'total_os',pm.total_os,'custo_total',pm.custo_total,'custo_medio',pm.custo_medio) FROM partner_metrics pm WHERE report_name='partners'
 UNION ALL SELECT tm.tipo,to_jsonb(tm) FROM type_metrics tm WHERE report_name='types'
 UNION ALL SELECT po.numero,jsonb_build_object('order_id',po.id,'numero',po.numero,'placa',v.placa,'filial',coalesce(br.nome,'Sem filial'),'oficina',coalesce(p.nome_fantasia,p.razao_social),'tipo',po.tipo,'status',po.status,'data_abertura',po.data_abertura,'encerrada_em',po.encerrada_em,'valor_total',CASE WHEN po.status='encerrada' THEN po.valor_total END) FROM period_orders po JOIN public.veiculos v ON v.id=po.vehicle_id JOIN public.maintenance_partners p ON p.id=po.partner_id LEFT JOIN public.maintenance_branches br ON br.id=po.branch_id WHERE report_name='history'
 UNION ALL SELECT vm.placa,jsonb_build_object('placa',vm.placa,'downtime_horas',vm.downtime_horas,'visitas_abertas',vm.visitas_abertas) FROM vehicle_metrics vm WHERE report_name='downtime' AND vm.downtime_horas>0)
 SELECT CASE WHEN action='report' THEN jsonb_build_object('rows',coalesce((SELECT jsonb_agg(rows_page.row_data) FROM (SELECT row_data FROM report_rows ORDER BY sort_key OFFSET (page_number-1)*page_size LIMIT page_size) rows_page),'[]'::jsonb),'count',(SELECT count(*) FROM report_rows),'page',page_number,'size',page_size)
 ELSE jsonb_build_object(
 'cards',jsonb_build_object('manutencao',(SELECT n FROM maintenance_now),'disponibilidade',CASE WHEN (SELECT count(*) FROM fleet)>0 THEN 100.0*(SELECT count(*) FROM fleet WHERE status NOT IN ('Bloqueado','Manutenção'))/nullif((SELECT count(*) FROM fleet),0) END,'abertas',(SELECT count(*) FROM active_orders),'atrasadas',(SELECT count(*) FROM active_orders WHERE previsao_entrega<clock_timestamp()),'aprovacao',(SELECT count(*) FROM active_orders ao WHERE orcamento_status='pendente' AND (status='aguardando_orcamento' OR EXISTS(SELECT 1 FROM public.maintenance_order_items i WHERE i.order_id=ao.id))),'peca',(SELECT count(*) FROM active_orders WHERE status='aguardando_peca'),'custo',(SELECT coalesce(sum(valor_total),0) FROM costs),'mttr_horas',(SELECT avg(extract(epoch FROM finished-started)/3600) FROM repair_pairs WHERE finished>=lo AND finished<hi AND finished>=started),'mttr_amostras',(SELECT count(*) FROM repair_pairs WHERE finished>=lo AND finished<hi AND finished>=started),'oficina_horas',(SELECT avg(extract(epoch FROM saida_em-chegada_em)/3600) FROM finished_visits)),
 'monthly',coalesce((SELECT jsonb_agg(to_jsonb(mo) ORDER BY mo.mes) FROM monthly mo),'[]'::jsonb),
 'mix',(SELECT jsonb_build_object('preventiva',count(*) FILTER(WHERE tipo='preventiva'),'corretiva',count(*) FILTER(WHERE tipo='corretiva')) FROM period_orders WHERE status<>'cancelada'),
 'vehicles',coalesce((SELECT jsonb_agg(to_jsonb(top_v)) FROM (SELECT vm.*,vm.custo_total/nullif(vm.km_observado,0) custo_km FROM vehicle_metrics vm ORDER BY vm.custo_total DESC,vm.placa LIMIT 10) top_v),'[]'::jsonb),
 'downtime',coalesce((SELECT jsonb_agg(to_jsonb(top_d)) FROM (SELECT vm.placa,vm.downtime_horas FROM vehicle_metrics vm WHERE vm.downtime_horas>0 ORDER BY vm.downtime_horas DESC,vm.placa LIMIT 10) top_d),'[]'::jsonb),
 'breakdowns',coalesce((SELECT jsonb_agg(to_jsonb(top_b)) FROM (SELECT vm.placa,vm.quebras FROM vehicle_metrics vm WHERE vm.quebras>0 ORDER BY vm.quebras DESC,vm.placa LIMIT 10) top_b),'[]'::jsonb),
 'workshops',coalesce((SELECT jsonb_agg(to_jsonb(pm) ORDER BY pm.sla_pct DESC NULLS LAST,pm.prazo_horas,pm.oficina) FROM partner_metrics pm),'[]'::jsonb),
 'critical',coalesce((SELECT jsonb_agg(to_jsonb(crit)) FROM (SELECT ao.id,ao.numero,v.placa,ao.status,ao.prioridade,ao.previsao_entrega,ao.previsao_entrega<clock_timestamp() atrasada FROM active_orders ao JOIN public.veiculos v ON v.id=ao.vehicle_id WHERE ao.prioridade='critica' OR ao.previsao_entrega<clock_timestamp() ORDER BY (ao.prioridade='critica') DESC,ao.previsao_entrega NULLS LAST,ao.numero LIMIT 20) crit),'[]'::jsonb)) END INTO result;
 RETURN result||jsonb_build_object('generated_at',clock_timestamp(),'start',date_start,'end',date_end);
END $$;
CREATE FUNCTION public.maintenance_analytics_command(target_company uuid,command text,body jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT maintenance_private.analytics_command(target_company,command,body);$$;
REVOKE ALL ON FUNCTION maintenance_private.analytics_command(uuid,text,jsonb),public.maintenance_analytics_command(uuid,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION maintenance_private.analytics_command(uuid,text,jsonb),public.maintenance_analytics_command(uuid,text,jsonb) TO authenticated;
COMMIT;
